// Get all models from all 4 searches
const allModels = $input.all().map(i => i.json);

// Reset the per-run candidate budget counter (caps Claude calls this run).
const sd = $getWorkflowStaticData('global');
sd.hfCandidateCount = 0;

// Extract the author from each model and deduplicate
const seen = new Set();
const uniqueAuthors = [];

for (const model of allModels) {
  const author = model.author || model.id?.split('/')[0];
  if (!author) continue;
  // Skip org accounts — we want individual engineers
  // (orgs typically have IDs without hyphens in the name)
  if (seen.has(author)) continue;
  seen.add(author);
  uniqueAuthors.push({
    hf_username: author,
    model_id: model.id,
    model_downloads: model.downloads || 0,
    model_likes: model.likes || 0,
    model_task: model.pipeline_tag || '',
    model_last_updated: model.lastModified || ''
  });
}

// Sort by downloads — highest first
uniqueAuthors.sort((a, b) => b.model_downloads - a.model_downloads);

// Return top 80 candidate authors. Orgs get skipped later (profile 404),
// and Claude scoring is capped separately by the "Within Test Budget?" gate.
return uniqueAuthors.slice(0, 80).map(a => ({ json: a }));

const hfProfile = $('Get HF Profile').first().json;
const modelData = $('Process One By One').first().json;
const githubResults = $input.first().json.items || [];
const github = githubResults[0] || {};

// Increment per-run candidate counter — this only runs for individuals
// (orgs 404 at the profile step and never reach here). Used to cap Claude usage.
const sd = $getWorkflowStaticData('global');
sd.hfCandidateCount = (sd.hfCandidateCount || 0) + 1;

// Format organisations as readable text
const orgs = (hfProfile.orgs || []).map(o => o.name || o.id).join(', ') || 'none listed';

return [{
  json: {
    hf_username: modelData.hf_username,
    full_name: hfProfile.fullname || modelData.hf_username,
    hf_url: `https://huggingface.co/${modelData.hf_username}`,
    bio: hfProfile.bio || 'no bio',
    location: hfProfile.location || 'unknown',
    website: hfProfile.website || '',
    num_models: hfProfile.numModels || 0,
    num_followers: hfProfile.numFollowers || 0,
    organisations: orgs,
    // The model that triggered this candidate
    top_model_id: modelData.model_id,
    top_model_downloads: modelData.model_downloads,
    top_model_task: modelData.model_task,
    top_model_last_updated: modelData.model_last_updated,
    // GitHub cross-reference
    github_url: github.html_url || '',
    github_followers: github.followers || 0,
    // Test budget tracking
    candidate_number: sd.hfCandidateCount
  }
}];

