const raw = $input.first().json.content[0].text;
const cleaned = raw.replace(/```json|```/g, '').trim();
const score = JSON.parse(cleaned);
const profile = $('Format for Claude').first().json;

return [{
  json: {
    // Identity
    full_name: profile.full_name,
    hf_url: profile.hf_url,
    github_url: profile.github_url,
    location_city: profile.location,

    // Source tracking
    source: 'Hugging Face',
    source_role: 'Senior ML Engineer', // EDIT THIS
    date_sourced: new Date().toISOString().split('T')[0],

    // Model data
    top_model_id: profile.top_model_id,
    top_model_downloads: profile.top_model_downloads,
    top_model_task: profile.top_model_task,
    num_models_published: profile.num_models,
    hf_followers: profile.num_followers,
    hf_organisations: profile.organisations,

    // Claude scores
    fit_score: score.fit_score,
    priority_action: score.priority,
    key_strengths: score.key_strengths.join(' | '),
    key_gaps: score.key_gaps.join(' | '),
    outreach_hook: score.outreach_hook,
    estimated_seniority: score.estimated_seniority,
    impact_signal: score.impact_signal
  }
}];
